  if (!r) { problems.push(`#${n}: veri yok`); continue; }
  const [durum, kanit, , dilim] = r;
  if (!(durum in sayac)) problems.push(`#${n}: geçersiz durum ${durum}`);
  else sayac[durum]++;
  if (!tr[n]) problems.push(`#${n}: Faz 0 matrisinde yok`);
